public class Main {
    public static void main(String[] args) {
        // Error budget: 1,000,000 requests, SLO 99.9% -> 1000 bad requests allowed
        long total = 1000000, sloPermille = 999;
        long budget = total * (1000 - sloPermille) / 1000; // allowed bad requests
        int[] badPerDay = {50, 30, 200, 20, 10, 300, 40, 0, 60, 100, 250};
        long used = 0;
        System.out.println("budget: " + budget + " bad requests");
        for (int i = 0; i < badPerDay.length; i++) {
            used += badPerDay[i];
            long left = budget - used;
            // policy agreed in advance: ship / slow down / freeze
            String state;
            if (left <= 0) state = "FREEZE";
            else if (left < budget / 4) state = "SLOW";
            else state = "SHIP";
            System.out.println("day " + (i + 1) + " used " + used + " left " + left + " " + state);
        }
    }
}

