public class Main {
    public static void main(String[] args) {
        // Little's law: in-flight requests L = arrival rate x time in system
        int rate = 200;   // requests per second
        int pool = 100;   // connection pool size
        int[] latenciesMs = {250, 500, 2500};
        for (int latencyMs : latenciesMs) {
            int inFlight = rate * latencyMs / 1000;
            String status = inFlight > pool ? "POOL EXHAUSTED" : "ok";
            System.out.println("rate " + rate + " rps, latency " + latencyMs + " ms -> in flight " + inFlight + " " + status);
        }
        // sizing: pool needed for 250 ms with 30% headroom
        int need = rate * 250 / 1000;
        System.out.println("pool with 30% headroom: " + (need * 130 / 100));
    }
}

