import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Toil payback: weeks until the automation pays for itself
        // each task: name, hours of toil per week, hours to build the fix
        String[] names = {"restart stuck job", "renew certs by hand", "grant user access", "clean old logs"};
        int[] perWeek = {3, 1, 5, 2};
        int[] build = {6, 10, 20, 6};
        int weekHours = 40, total = 0;
        for (int h : perWeek) total += h;
        System.out.println("toil: " + total + " of " + weekHours + " hours a week = " + (total * 100 / weekHours) + " percent");
        List<int[]> rows = new ArrayList<>();
        for (int i = 0; i < names.length; i++) {
            int payback = (build[i] + perWeek[i] - 1) / perWeek[i]; // round up to whole weeks
            rows.add(new int[]{payback, i});
        }
        rows.sort((a, b) -> a[0] - b[0]);                           // shortest payback first
        for (int[] r : rows) System.out.println("payback " + r[0] + " weeks: " + names[r[1]]);
    }
}

