public class Main {
    static final long M = 1000000; // availability in parts per million (ppm)

    static long serial(long[] parts) {   // every part must work: multiply
        long s = M;
        for (long p : parts) s = s * p / M;
        return s;
    }

    static long parallel(long p, int n) { // n copies: fails only if all fail
        long fail = M;
        for (int i = 0; i < n; i++) fail = fail * (M - p) / M;
        return M - fail;
    }

    public static void main(String[] args) {
        long lb = 999900, api = 995000, db = 999500;
        long one = serial(new long[]{lb, api, db});
        long two = serial(new long[]{lb, parallel(api, 2), db});
        long minutes = 43200; // one 30-day month
        System.out.println("one API copy : " + one + " ppm, downtime " + ((M - one) * minutes / M) + " min/month");
        System.out.println("two API copies: " + two + " ppm, downtime " + ((M - two) * minutes / M) + " min/month");
    }
}

